import re


def normalize_spaces(text):
    '''Collapse repeated whitespace and trim the ends.'''
    return " ".join(text.split())


def slugify(text):
    '''Lowercase text, replace runs of non-alphanumeric characters with a single hyphen, and trim hyphens from both ends.'''
    text = text.lower()
    text = re.sub(r'[^a-z0-9]+', '-', text)
    return text.strip('-')

