import pytest

import text_utils


def test_normalize_spaces_collapses_multiple_internal_spaces():
    assert text_utils.normalize_spaces("one   two    three") == "one two three"


def test_normalize_spaces_trims_leading_and_trailing_spaces():
    assert text_utils.normalize_spaces("  leading and trailing  ") == "leading and trailing"


def test_normalize_spaces_collapses_mixed_whitespace():
    assert text_utils.normalize_spaces("a\t\tb\nc\r\nd") == "a b c d"


def test_normalize_spaces_empty_string_returns_empty():
    assert text_utils.normalize_spaces("") == ""


def test_normalize_spaces_whitespace_only_returns_empty():
    assert text_utils.normalize_spaces("   \t\n  ") == ""


def test_normalize_spaces_single_word_unchanged():
    assert text_utils.normalize_spaces("single") == "single"


def test_normalize_spaces_already_normalized_unchanged():
    assert text_utils.normalize_spaces("already normal") == "already normal"


def test_normalize_spaces_none_raises_attribute_error():
    with pytest.raises(AttributeError):
        text_utils.normalize_spaces(None)
